# -*- coding: utf-8 -*-
"""Deutschland / Klasse 10（Biologie, Chemie, Physik）"""
from de_sci import H, nq, num


def f_halb(R):
    k = R.choice(["rest", "rest", "zeit", "anzahl"])
    if k == "rest":
        m0, T, n = R.choice([(80, 8, 2), (64, 5, 3), (200, 30, 1), (120, 12, 2), (40, 3, 3), (96, 6, 4), (1000, 28, 2), (16, 2, 4), (48, 10, 3), (72, 15, 3), (60, 7, 2), (256, 9, 4), (36, 20, 2), (90, 11, 1), (320, 4, 3)])
        rest = m0 / 2 ** n
        return nq("Ein Stoff hat die Halbwertszeit %s Tage. Von %s mg sind nach %s Tagen noch wie viele mg übrig?" % (num(T), num(m0), num(T * n)), rest,
                  [m0 / (2 * n), m0 - m0 / 2 * n if m0 - m0 / 2 * n > 0 else m0 / 2 ** (n + 1), m0 / 2 ** (n - 1) if n > 1 else m0 * 0.75], "mg",
                  "%s Tage sind %d Halbwertszeiten: %s mg · (½)%s = %s mg." % (num(T * n), n, num(m0), str(n).translate(str.maketrans("0123456789", "⁰¹²³⁴⁵⁶⁷⁸⁹")), num(rest)))
    if k == "zeit":
        T, n = R.choice([(8, 3), (5, 2), (30, 2), (12, 4), (3, 5), (6, 3), (2, 4), (10, 2), (4, 5), (15, 2), (20, 3), (7, 4)])
        return nq("Ein Präparat hat die Halbwertszeit %s Stunden. Nach welcher Zeit ist nur noch 1/%d der Aktivität übrig?" % (num(T), 2 ** n), T * n,
                  [T * 2 ** n, T * n / 2, T + n], "h", "1/%d = (½)%s, also %d Halbwertszeiten: %d · %s h = %s h." % (2 ** n, str(n).translate(str.maketrans("0123456789", "⁰¹²³⁴⁵⁶⁷⁸⁹")), n, n, num(T), num(T * n)))
    N, n = R.choice([(8000, 3), (1200, 2), (6400, 4), (3000, 1), (10000, 2), (4800, 3)])
    return nq("Eine Probe enthält %s instabile Kerne. Wie viele sind nach %d Halbwertszeiten noch nicht zerfallen?" % (num(N), n), N / 2 ** n,
              [N / (2 * n), N - N / 2 ** n, N / 2 ** (n + 1)], "", "Nach jeder Halbwertszeit halbiert sich die Zahl: %s : %d = %s." % (num(N), 2 ** n, num(N / 2 ** n)))


def f_beschl(R):
    k = R.choice(["a", "a", "v", "s", "fall"])
    if k == "a":
        dv, t = R.choice([(20, 5), (27, 9), (12, 4), (30, 6), (10, 8), (100, 2), (15, 3), (24, 12)])
        return nq("Ein Auto beschleunigt in %s s von 0 auf %s m/s. Wie groß ist die Beschleunigung?" % (num(t), num(dv)), dv / t, [dv * t, t / dv, dv - t], "m/s²",
                  "a = Δv : Δt = %s m/s : %s s = %s m/s²." % (num(dv), num(t), num(dv / t)))
    if k == "v":
        a, t = R.choice([(2, 5), (3, 4), (1.5, 10), (4, 6), (0.5, 20), (2.5, 8)])
        return nq("Ein Fahrzeug startet aus dem Stand mit %s m/s². Wie schnell ist es nach %s s?" % (num(a), num(t)), a * t, [a / t, a * t * t / 2, a + t], "m/s",
                  "v = a · t = %s m/s² · %s s = %s m/s." % (num(a), num(t), num(a * t)))
    if k == "s":
        a, t = R.choice([(2, 5), (4, 3), (1, 10), (3, 4), (2, 8), (6, 2)])
        return nq("Ein Körper startet aus der Ruhe mit %s m/s². Welchen Weg legt er in %s s zurück?" % (num(a), num(t)), a * t * t / 2, [a * t, a * t * t, a * t / 2], "m",
                  "s = ½ · a · t² = 0,5 · %s m/s² · (%s s)² = %s m." % (num(a), num(t), num(a * t * t / 2)))
    t = R.choice([1, 2, 3, 4, 1.5, 0.5])
    return nq("Ein Stein fällt frei aus der Ruhe. Welche Geschwindigkeit hat er nach %s s? (g ≈ 10 m/s², ohne Luftwiderstand)" % num(t), 10 * t, [5 * t * t, 10 * t * t, 10 / t], "m/s",
              "v = g · t = 10 m/s² · %s s = %s m/s." % (num(t), num(10 * t)))


def f_newton(R):
    k = R.choice(["F", "F", "a", "m", "reib"])
    if k == "F":
        m, a = R.choice([(1200, 2), (60, 3), (0.5, 8), (1500, 4), (80, 1.5), (2, 5), (1000, 0.5), (70, 2)])
        return nq("Welche Kraft beschleunigt einen Körper mit %s kg mit %s m/s²?" % (num(m), num(a)), m * a, [m / a, a / m, m + a], "N",
                  "F = m · a = %s kg · %s m/s² = %s N." % (num(m), num(a), num(m * a)))
    if k == "a":
        F, m = R.choice([(600, 200), (3000, 1500), (90, 30), (40, 8), (5000, 1000), (12, 4), (450, 90)])
        return nq("Auf einen Wagen mit %s kg wirkt die Kraft %s N. Wie groß ist die Beschleunigung?" % (num(m), num(F)), F / m, [F * m, m / F, F - m], "m/s²",
                  "a = F : m = %s N : %s kg = %s m/s²." % (num(F), num(m), num(F / m)))
    if k == "m":
        F, a = R.choice([(500, 2), (60, 3), (2400, 1.2), (100, 4), (900, 3), (36, 6)])
        return nq("Eine Kraft von %s N beschleunigt einen Körper mit %s m/s². Welche Masse hat er?" % (num(F), num(a)), F / a, [F * a, a / F, F - a], "kg",
                  "m = F : a = %s N : %s m/s² = %s kg." % (num(F), num(a), num(F / a)))
    F, Fr, m = R.choice([(500, 200, 100), (1000, 400, 300), (80, 20, 30), (3000, 1200, 900), (60, 15, 9)])
    return nq("Ein Schlitten (%s kg) wird mit %s N gezogen, die Reibung beträgt %s N. Wie groß ist die Beschleunigung?" % (num(m), num(F), num(Fr)), (F - Fr) / m,
              [F / m, (F + Fr) / m, Fr / m], "m/s²", "Die resultierende Kraft ist %s N − %s N = %s N; a = %s N : %s kg = %s m/s²." % (num(F), num(Fr), num(F - Fr), num(F - Fr), num(m), num((F - Fr) / m)))


