          "Fast jedes Kraftwerk treibt einen Generator an", "Erneuerbare Energien wie Wind und Sonne erzeugen Strom ohne CO₂-Ausstoß im Betrieb.",
          ["Bei der Kernspaltung zerfällt ein Uran-235-Kern nach dem Einfang eines Neutrons in zwei kleinere Kerne. Dabei werden Energie und weitere Neutronen frei: eine Kettenreaktion.",
           "In der Sonne verschmelzen Wasserstoffkerne zu Helium: Kernfusion. In Kohle-, Gas- und Kernkraftwerken erzeugt Wärme Dampf, der eine Turbine mit Generator antreibt.",
           "Fossile Brennstoffe setzen CO₂ frei und verstärken den Treibhauseffekt. Deutschland setzt bei der Energiewende auf Wind, Sonne, Biomasse und Wasserkraft, dazu braucht man Netze und Speicher."],
          [("Warum braucht man Stromspeicher, wenn viele Solaranlagen ins Netz einspeisen?", ["Die Sonne scheint nicht nachts.", "Strom muss erzeugt werden, wenn er gebraucht wird."], "Um Strom für Zeiten ohne Sonne aufzuheben.")],
          [("Solarzellen erzeugen Strom mit einer Turbine.", "Solarzellen wandeln Licht direkt in elektrische Energie um."), ("Kernkraftwerke nutzen Kernfusion.", "Kernkraftwerke nutzen Kernspaltung."),
           ("Erneuerbare Energien gehen irgendwann aus.", "Wind, Sonne und Wasser stehen dauerhaft zur Verfügung.")],
          [("Wann ging das letzte deutsche Kernkraftwerk vom Netz?", "Am 15. April 2023 wurden die letzten drei Kernkraftwerke abgeschaltet."), ("Was ist ein Pumpspeicherkraftwerk?", "Bei Stromüberschuss wird Wasser nach oben gepumpt. Bei Bedarf treibt es beim Herabfließen Turbinen an."),
           ("Warum ist Atommüll ein Problem?", "Er strahlt Tausende Jahre und muss sicher gelagert werden.")],
          [("Kraftwerke", [("Kohlekraftwerk", "chemische Energie in elektrische Energie"), ("Windkraftanlage", "Bewegungsenergie der Luft in elektrische Energie"), ("Solarzelle", "Strahlungsenergie in elektrische Energie"),
                           ("Wasserkraftwerk", "Lageenergie des Wassers in elektrische Energie"), ("Kernkraftwerk", "Kernenergie in elektrische Energie"), ("Geothermiekraftwerk", "Erdwärme in elektrische Energie"),
                           ("Biogasanlage", "chemische Energie aus Pflanzen und Gülle in elektrische Energie")],
            "Welche Umwandlung findet statt? {k}", "Welche Anlage wandelt {v} um?"),
           ("Erneuerbar oder nicht?", {"den erneuerbaren Energien": ["Windenergie", "Sonnenenergie", "Wasserkraft", "Erdwärme", "Biomasse", "Gezeitenenergie"],
                                       "den nicht erneuerbaren Energieträgern": ["Braunkohle", "Steinkohle", "Erdgas", "Erdöl", "Uran"]}),
           ("Kernphysik", [("Kernspaltung", "schwerer Kern zerfällt in zwei kleinere"), ("Kernfusion", "leichte Kerne verschmelzen"), ("Kettenreaktion", "frei werdende Neutronen spalten weitere Kerne"),
                           ("Moderator", "bremst Neutronen im Reaktor ab"), ("Steuerstäbe", "fangen Neutronen ein und regeln die Kettenreaktion"), ("Endlager", "sicherer Ort für radioaktive Abfälle"),
                           ("Uran-235", "spaltbarer Brennstoff im Kernkraftwerk")],
            "Was ist {k}?", "Was ist gemeint? {v}")],
          ["In der Sonne findet Kernfusion statt.", "Kernkraftwerke nutzen Kernspaltung.", "Bei der Kernspaltung werden Neutronen frei.", "Kohlekraftwerke setzen Kohlenstoffdioxid frei.",
           "Windenergie ist erneuerbar.", "Solarzellen wandeln Licht direkt in Strom um.", "Für die Energiewende braucht man Speicher.", "Steuerstäbe regeln die Kettenreaktion."],
          [("Kernkraftwerke nutzen Kernfusion.", "Sie nutzen Kernspaltung."), ("Erdgas ist erneuerbar.", "Erdgas ist fossil."), ("Solarzellen treiben eine Turbine an.", "Sie wandeln Licht direkt in Strom um."),
           ("In der Sonne werden Urankerne gespalten.", "Dort verschmelzen Wasserstoffkerne."), ("Atommüll strahlt nur wenige Tage.", "Er strahlt Tausende Jahre."), ("Windkraft setzt im Betrieb viel CO₂ frei.", "Im Betrieb entsteht kein CO₂.")],
